// отсортированный массив: O(n) время, O(1) память
int lo = 0, hi = nums.Length - 1;
while (lo < hi) {
    int sum = nums[lo] + nums[hi];
    if (sum == target) return new[] { lo, hi };
    if (sum < target) lo++;   // с nums[lo] мала даже сумма с самым большим
    else hi--;                // с nums[hi] велика даже сумма с самым маленьким
}
